/* Runs production input/target source. No third-party DOM or browser dependency. */
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),cp=require('./portable-baseline.cjs');
const {base,Element,event,fan}=require('./observation-harness.cjs');
const {geometry}=require('./audit-structural-sequences.cjs');
const root=path.resolve(__dirname,'../..'),baseline=process.argv.includes('--baseline');
const read=(repo,file)=>baseline?cp.execFileSync('git',['-C',path.join(root,repo),'show',`HEAD:${file}`],{encoding:'utf8'}):fs.readFileSync(path.join(root,repo,file),'utf8');
const washerSource=read('washer-study','dist/index.html'),fanSource=read('fan-study','dist/fan.js');
function washer(){
 const h=base(),svg=new Element('svg'),target=new Element('path'),buttons={vreset:new Element('button'),vspin:new Element('button')};target.dataset.act='sample';svg.append(target);let activations=0;
 Object.assign(h.ctx,{svg,cfg:{acts:{sample(){activations++}}},st:{},YAW:45,PITCH:35,YAW0:45,PITCH0:35,ease:x=>x,document:{hidden:false,activeElement:target,addEventListener:(n,f)=>(h.docs[n]??=[]).push(f),getElementById:n=>buttons[n]},ui:{animate:f=>h.steps.push(f),invalidate(){},press(name){this.pressedAct=name},clearPress(){this.pressedAct=null}}});
 h.ctx.setCam=(y,p)=>{h.ctx.YAW=y;h.ctx.PITCH=p};h.run(washerSource.slice(washerSource.indexOf('  let drag = null'),washerSource.indexOf("  if (q.has('yaw')")));
 const key=(target,key,extra={})=>{const e=event(target,{key,...extra});if(target===svg||target.parent===svg){for(const fn of svg.events.keydown||[])fn(e)}h.emit('keydown',e);return e};
 return {...h,svg,target,buttons,key,activations:()=>activations};
}
function washerTargets(){
 const h=geometry('washer-study',washerSource),document=h.ctx.document,svg=new Element('svg'),hitLayer=new Element('g'),hitNodes=new Map();svg.append(hitLayer);document.activeElement=null;
 document.createElementNS=(ns,tag)=>{const node=new Element(tag);node.removeAttribute=k=>delete node.attrs[k];node.matches=()=>false;node.remove=()=>{node.parent.children=node.parent.children.filter(x=>x!==node);if(document.activeElement===node)document.activeElement=null;node.parent=null};node.focus=options=>{document.activeElement=node;node.focusOptions=options};return node};svg.focus=options=>{document.activeElement=svg;svg.focusOptions=options};
 Object.assign(h.ctx,{NS:'http://www.w3.org/2000/svg',sceneSvg:svg,hitLayer,hitNodes,hint:new Element(),targetClipShape:new Element(),ui:{st:h.run('st')},locked:s=>s.run||!!s.latch});
 const start=washerSource.indexOf('ui.updateTargets=()=>{');h.run(washerSource.slice(start,washerSource.indexOf('\nui.render();',start)));h.run('setCam(38,23);ui.updateTargets()');return {...h,svg,hitNodes,document};
}
const results=[];
function test(name,fn){try{fn();results.push({name,pass:true});console.log('PASS',name)}catch(e){results.push({name,pass:false,error:e.message});console.log('FAIL',name,'\n ',e.message)}}
test('Washer settings summary/scroll region and panel keys do not orbit or prevent default',()=>{const h=washer();for(const tag of ['summary','section','button','input','textarea'])for(const key of ['ArrowLeft','ArrowRight','ArrowUp','ArrowDown']){const e=h.key(new Element(tag),key);assert(!e.defaultPrevented,tag+' '+key);h.advance(300);assert.equal(h.ctx.YAW,45);assert.equal(h.ctx.PITCH,35)}});
test('Washer focused scene arrows orbit but Alt/Ctrl/Meta combinations pass through',()=>{const h=washer();for(const modifier of ['altKey','ctrlKey','metaKey'])for(const key of ['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Enter',' ']){const e=h.key(h.target,key,{[modifier]:true});assert(!e.defaultPrevented,modifier+' '+key)}assert.equal(h.activations(),0);assert.equal(h.steps.length,0);assert(h.key(h.target,'ArrowRight').defaultPrevented);h.advance(300);assert.equal(h.ctx.YAW,60)});
test('Washer click-only controls activate once each; pointer click is not doubled',()=>{const h=washer();h.svg.emit('click',{target:h.target,detail:0});h.svg.emit('click',{target:h.target,detail:0});assert.equal(h.activations(),2);h.svg.emit('pointerdown',{target:h.target});h.svg.emit('pointerup',{target:h.target});h.svg.emit('click',{target:h.target,detail:1});assert.equal(h.activations(),3)});
test('Washer Enter/Space plus synthesized click and repeat activate only once per press',()=>{for(const key of ['Enter',' ']){const h=washer();h.key(h.target,key);h.svg.emit('click',{target:h.target,detail:0});h.key(h.target,key,{repeat:true});h.svg.emit('click',{target:h.target,detail:0});h.svg.emit('keyup',{target:h.target,key});h.svg.emit('click',{target:h.target,detail:0});assert.equal(h.activations(),1);h.advance(20);h.svg.emit('click',{target:h.target,detail:0});h.svg.emit('click',{target:h.target,detail:0});assert.equal(h.activations(),3)}});
test('Washer blur/hidden interrupts held keyboard session without blocking later click-only input',()=>{for(const interrupt of ['blur','hidden']){const h=washer();h.key(h.target,'Enter');if(interrupt==='blur')h.emit('blur');else{h.ctx.document.hidden=true;h.emitDoc('visibilitychange')}h.svg.emit('click',{target:h.target,detail:0});assert.equal(h.activations(),2);assert.equal(h.ctx.ui.pressedAct,null)}});
test('Washer loading removes focused basket but retains focus in model without scrolling',()=>{const h=washerTargets(),basket=h.hitNodes.get('laundry');assert(basket);basket.focus();h.run('ui.st.loading=true;ui.updateTargets()');assert(!h.hitNodes.has('laundry'));assert(h.document.activeElement===h.svg,'Focus remains in the model');assert.equal(h.svg.focusOptions?.preventScroll,true);assert.match(washerSource,/<svg id="fig"[^>]*tabindex="0"/)});
test('Washer rear-hidden removal retains model focus but never steals panel focus',()=>{const h=washerTargets(),start=h.hitNodes.get('start');assert(start);start.focus();h.run('setCam(180,6);ui.updateTargets()');assert(h.document.activeElement===h.svg,'Focus remains in the model');const panel=new Element('button');h.document.activeElement=panel;h.run('setCam(38,23);ui.updateTargets();setCam(180,6);ui.updateTargets()');assert.equal(h.document.activeElement,panel)});
test('Washer reset uses shortest path after positive and negative full turns',()=>{for(const yaw of [45+360*6+20,45-360*6-20,45+360*20+170,45-360*20-170]){const h=washer();h.ctx.YAW=yaw;h.buttons.vreset.onclick();h.advance(750);assert(Math.abs(h.ctx.YAW-yaw)<=180);assert(Math.abs(((h.ctx.YAW-45)%360+360)%360)<.001)}});
test('Washer reset/double-click stop old spin, and rapid spin toggles do not duplicate speed',()=>{for(const reset of ['button','doubleclick']){const h=washer();h.buttons.vspin.onclick();h.buttons.vspin.onclick();h.buttons.vspin.onclick();h.advance(1000);assert(Math.abs(h.ctx.YAW-63)<.01);if(reset==='button')h.buttons.vreset.onclick();else h.svg.emit('dblclick');h.advance(800);const yaw=h.ctx.YAW;h.advance(1000);assert.equal(h.ctx.YAW,yaw);assert.equal(h.buttons.vspin.attrs['aria-pressed'],'false');assert.equal(h.steps.length,0)}});
test('Fan Alt/Ctrl/Meta shortcuts pass through without camera or control changes',()=>{const h=fan(fanSource),target=h.targets[0];for(const modifier of ['altKey','ctrlKey','metaKey'])for(const key of ['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Enter',' ']){const e=event(target,{key,[modifier]:true});h.ids.figure.onkeydown(e);assert(!e.defaultPrevented,modifier+' '+key)}assert.equal(h.run('engine.yaw'),-.4);assert.equal(h.run('engine.pitch'),.19);assert.equal(h.run('state.on'),false)});
test('Fan click-only remains repeatable; pointer click does not toggle twice',()=>{const h=fan(fanSource),target=h.targets[0];target.onclick(event(target,{detail:0}));assert.equal(h.run('state.on'),true);target.onclick(event(target,{detail:0}));assert.equal(h.run('state.on'),false);h.ids.figure.onpointerdown(event(target));h.ids.figure.onpointerup(event(target));target.onclick(event(target,{detail:1}));assert.equal(h.run('state.on'),true)});
test('Fan Enter/Space plus synthesized click and repeats activate once, then click-only works',()=>{for(const key of ['Enter',' ']){const h=fan(fanSource),target=h.targets[0];h.ids.figure.onkeydown(event(target,{key}));target.onclick(event(target,{detail:0}));h.ids.figure.onkeydown(event(target,{key,repeat:true}));target.onclick(event(target,{detail:0}));h.ids.figure.onkeyup?.(event(target,{key}));target.onclick(event(target,{detail:0}));assert.equal(h.run('state.on'),true);h.advance(20);target.onclick(event(target,{detail:0}));assert.equal(h.run('state.on'),false);target.onclick(event(target,{detail:0}));assert.equal(h.run('state.on'),true)}});
test('Fan blur/hidden ends keyboard click deduplication without affecting independent input',()=>{for(const interrupt of ['blur','hidden']){const h=fan(fanSource),target=h.targets[0];h.ids.figure.onkeydown(event(target,{key:'Enter'}));if(interrupt==='blur')h.emit('blur');else{h.ctx.document.hidden=true;h.emitDoc('visibilitychange')}target.onclick(event(target,{detail:0}));assert.equal(h.run('state.on'),false)}});
test('Washer matching pointer detail-zero click is deduplicated after tap, drag or cancellation',()=>{for(const pointerType of ['mouse','touch','pen'])for(const finish of ['tap','drag','cancel']){const h=washer(),pointer={target:h.target,pointerId:17,pointerType};h.svg.emit('pointerdown',pointer);if(finish==='drag')h.svg.emit('pointermove',{...pointer,clientX:160});h.svg.emit(finish==='cancel'?'pointercancel':'pointerup',pointer);const expected=finish==='tap'?1:0;assert.equal(h.activations(),expected);h.svg.emit('click',{...pointer,detail:0});assert.equal(h.activations(),expected,pointerType+' '+finish+' compatibility click');for(let i=1;i<=2;i++){h.svg.emit('click',{target:h.target,detail:0,pointerId:undefined,pointerType:undefined});assert.equal(h.activations(),expected+i,'Independent click-only activation stays repeatable')}}});
test('Fan matching pointer detail-zero click is deduplicated after tap, drag or cancellation',()=>{for(const pointerType of ['mouse','touch','pen'])for(const finish of ['tap','drag','cancel']){const h=fan(fanSource),target=h.targets[0],pointer=event(target,{pointerId:17,pointerType});h.ids.figure.onpointerdown(pointer);if(finish==='drag')h.ids.figure.onpointermove({...pointer,clientX:160});h.ids.figure[finish==='cancel'?'onpointercancel':'onpointerup'](pointer);const expected=finish==='tap';assert.equal(h.run('state.on'),expected);target.onclick({...pointer,detail:0});assert.equal(h.run('state.on'),expected,pointerType+' '+finish+' compatibility click');target.onclick(event(target,{detail:0,pointerId:undefined,pointerType:undefined}));assert.equal(h.run('state.on'),!expected);target.onclick(event(target,{detail:0,pointerId:undefined,pointerType:undefined}));assert.equal(h.run('state.on'),expected)}});
console.log(JSON.stringify({mode:baseline?'HEAD before patch':'working tree',passed:results.filter(x=>x.pass).length,total:results.length,failures:results.filter(x=>!x.pass)},null,2));if(results.some(x=>!x.pass))process.exitCode=1;
